CREATE OR REPLACE FUNCTION public.act2_collection_search(p_search text DEFAULT ''::text, p_category text DEFAULT ''::text, p_subject text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result_ jsonb;
begin
 perform portal_private.require_current_session();
 if not public.act2_collection_staff() then raise exception 'forbidden'; end if;
 if length(coalesce(p_search,''))>200 then raise exception 'invalid_search'; end if;
 select coalesce(jsonb_agg(to_jsonb(r) order by r.category,r.filename),'[]'::jsonb) into result_ from (
 select d.id,d.filename,d.category,d.subject,d.notes,d.page_count,d.size_bytes,
 coalesce((select jsonb_agg((v->>'page')::int order by (v->>'page')::int)
 from jsonb_array_elements(d.page_text) v where coalesce(p_search,'')<>'' and strpos(lower(v->>'text'),lower(p_search))>0),'[]'::jsonb) matching_pages
 from public.act2_collection_documents d
 where (coalesce(p_category,'')='' or d.category=p_category) and (coalesce(p_subject,'')='' or d.subject=p_subject)
 and (coalesce(p_search,'')='' or strpos(lower(concat_ws(' ',d.filename,d.notes,d.category,d.subject)),lower(p_search))>0
 or exists(select 1 from jsonb_array_elements(d.page_text) v where strpos(lower(v->>'text'),lower(p_search))>0))
 ) r;
 return result_;
end $function$

CREATE OR REPLACE FUNCTION public.registration_review(p_actor uuid, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.student_registration_requests;t text;g uuid;starts timestamptz;ends timestamptz;decision text;
begin
 if not exists(select 1 from public.profiles where id=p_actor and role='admin' and status='active') then raise exception 'admin_required'; end if;
 select * into r from public.student_registration_requests where id=p_id for update;
 if not found then raise exception 'request_not_found'; end if;
 decision:=p_data->>'decision';
 if decision is null or decision not in ('approved','rejected') then raise exception 'invalid_decision'; end if;
 if r.status=decision then return jsonb_build_object('status',r.status); end if;
 if r.status<>'pending' then raise exception 'request_already_reviewed'; end if;
 if not exists(select 1 from public.profiles where id=r.user_id and role='student' and status='suspended') then raise exception 'account_changed_refresh'; end if;
 if decision='approved' then
  t:=p_data->>'track_id';g:=nullif(p_data->>'group_id','')::uuid;starts:=nullif(p_data->>'starts_at','')::timestamptz;ends:=nullif(p_data->>'ends_at','')::timestamptz;
  if not exists(select 1 from public.tracks where id=t and is_active) then raise exception 'invalid_track'; end if;
  if g is not null and not exists(select 1 from public.groups where id=g and track_id=t) then raise exception 'group_course_mismatch'; end if;
  if ends is not null and ends<=coalesce(starts,now()) then raise exception 'end_must_follow_start'; end if;
  if exists(select 1 from public.enrollments where user_id=r.user_id) then raise exception 'account_changed_refresh'; end if;
  perform public.enrol_student(r.user_id,t,p_actor);
  update public.enrollments set starts_at=starts,ends_at=ends,course_label=coalesce((select name from public.groups where id=g),'') where user_id=r.user_id and track_id=t;
  if g is not null then insert into public.group_members(group_id,user_id) values(g,r.user_id) on conflict do nothing; end if;
  update public.profiles set status='active' where id=r.user_id;
 end if;
 update public.student_registration_requests set status=decision,reviewed_at=now(),reviewed_by=p_actor,approved_group_id=g where id=r.id;
 insert into public.audit_log(actor_id,action,target_type,target_id,meta) values(p_actor,'registration.'||decision,'user',r.user_id::text,jsonb_build_object('request_id',r.id,'track_id',t,'group_id',g));
 return jsonb_build_object('status',decision);
end $function$

CREATE OR REPLACE FUNCTION portal_private.question_eligible(p_q questions, p_k question_keys, p_track text, p_daily boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare visual_ boolean; figures_ jsonb;
begin
 if p_q.id is null or p_q.track_id is distinct from p_track or p_k.question_id is distinct from p_q.id
  or nullif(btrim(p_q.stem),'') is null or nullif(btrim(p_k.explanation),'') is null
  or nullif(btrim(p_q.assets->>'release_hold_reason'),'') is not null
  or lower(coalesce(p_q.assets->>'bank_removed','false'))='true'
  or coalesce(p_k.correct->>'void','false')='true'
 then return false; end if;
 figures_:=case jsonb_typeof(p_q.assets->'figure') when 'array' then p_q.assets->'figure'
  when 'string' then jsonb_build_array(p_q.assets->'figure') else '[]'::jsonb end;
 visual_:=exists(select 1 from jsonb_array_elements_text(figures_) f where
  f ~ '^https://' or f ~ '^data:image/(png|jpeg|jpg|webp|gif|svg\+xml);base64,[A-Za-z0-9+/=[:space:]]+$')
  or coalesce(p_q.assets->>'image','') ~ '^https://'
  or nullif(btrim(p_q.assets->>'svg'),'') is not null
  or nullif(btrim(p_q.assets->>'html'),'') is not null
  or (jsonb_typeof(p_q.assets->'figspec')='object' and p_q.assets->'figspec'<>'{}'::jsonb);
 visual_:=coalesce(visual_,false);
 if lower(coalesce(p_q.assets->>'figure_required','false'))='true' and not visual_ then return false; end if;
 if p_q.type='mcq' then
  if jsonb_typeof(p_q.choices) is distinct from 'array' then return false; end if;
  if jsonb_array_length(p_q.choices) not between 2 and 8
   or exists(select 1 from jsonb_array_elements(p_q.choices) c where nullif(btrim(c->>'key'),'') is null)
   or (select count(distinct c->>'key') from jsonb_array_elements(p_q.choices) c)<>jsonb_array_length(p_q.choices)
  then return false; end if;
  if jsonb_typeof(p_k.correct)='string' then
   if not exists(select 1 from jsonb_array_elements(p_q.choices) c where c->>'key'=p_k.correct#>>'{}') then return false; end if;
  elsif jsonb_typeof(p_k.correct)='array' then
   if jsonb_array_length(p_k.correct)=0 or exists(select 1 from jsonb_array_elements(p_k.correct) a
    where jsonb_typeof(a)<>'string' or not exists(select 1 from jsonb_array_elements(p_q.choices) c where c->>'key'=a#>>'{}')) then return false; end if;
  else return false; end if;
  if not visual_ and exists(select 1 from jsonb_array_elements(p_q.choices) c where
   nullif(btrim(c->>'text'),'') is null or c->>'text' ilike '%in the original question%') then return false; end if;
 elsif p_q.type='grid_in' then
  if jsonb_typeof(p_k.correct) in ('string','number') then
   if nullif(btrim(p_k.correct#>>'{}'),'') is null then return false; end if;
  elsif jsonb_typeof(p_k.correct)='array' then
   if jsonb_array_length(p_k.correct)=0 or exists(select 1 from jsonb_array_elements(p_k.correct) a
    where jsonb_typeof(a) not in ('string','number') or nullif(btrim(a#>>'{}'),'') is null) then return false; end if;
  else return false; end if;
 else return false; end if;
 if p_daily then
  if p_q.type<>'mcq' or jsonb_typeof(p_k.correct)<>'string' or jsonb_array_length(p_q.choices)<4
   or nullif(p_q.assets->>'verified_release','') is null
   or exists(select 1 from jsonb_array_elements(p_q.choices) c where nullif(btrim(c->>'text'),'') is null
    or c->>'text' ilike '%in the original question%') then return false; end if;
 end if;
 return true;
end $function$
